import math


_MARGIN = 2
_FIXED_WIDTHS = (18, 14, 12)


def _cell(value, size):
    return value[:size].ljust(size)


def render_parcel_manifest(parcels, width=76):
    if not isinstance(parcels, list):
        raise TypeError("parcels must be a list")
    if isinstance(width, bool) or not isinstance(width, int):
        raise TypeError("width must be an integer")
    if width < 47:
        raise ValueError("width is too small")

    validated = []
    for parcel in parcels:
        if not isinstance(parcel, dict):
            raise TypeError("each parcel must be a dictionary")
        required = ("tracking", "zone", "weight", "note")
        if any(key not in parcel for key in required):
            raise ValueError("parcel is missing a required field")
        if any(not isinstance(parcel[key], str) for key in ("tracking", "zone", "note")):
            raise TypeError("parcel text fields must be strings")
        weight = parcel["weight"]
        if isinstance(weight, bool) or not isinstance(weight, (int, float)):
            raise TypeError("weight must be numeric")
        if not math.isfinite(weight) or weight < 0:
            raise ValueError("weight must be finite and non-negative")
        validated.append((parcel["tracking"], parcel["zone"], weight, parcel["note"]))

    note_width = width - _MARGIN - sum(_FIXED_WIDTHS)

    def row(tracking, zone, weight, note):
        return (
            " " * _MARGIN
            + _cell(tracking, 18)
            + _cell(zone, 14)
            + _cell(weight, 12)
            + _cell(note, note_width)
        )

    lines = [row("Tracking", "Zone", "Weight", "Note")]
    separator = " " * _MARGIN + "-" * width
    lines.append(separator)
    for tracking, zone, weight, note in validated:
        lines.append(row(tracking, zone, f"{weight:.1f}", note))
        lines.append(separator)
    return "\n".join(lines)

